INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch07$PT156-S2-Q21$batch07$, 156, 2, 21, $batch07$Flaw$batch07$, $batch07$Philosopher: For some kinds of art, there is truth to the adage that beauty is in the eye of the beholder. A painting or sculpture that strikes one person as having artistic value may strike another as lacking such value. Consequently, there are no valid objective standards for determining the artistic value of a painting or a sculpture.$batch07$, $batch07$The philosopher’s reasoning is flawed because it$batch07$, $batch07$D$batch07$, true, $batch07$Batch 07; question text from local bank.$batch07$ FROM lr_sections s WHERE s.preptest=156 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT156-S2-Q21$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$A$batch07$, $batch07$relies exclusively on an old adage whose truth has not been demonstrated$batch07$, $batch07$Bad Description$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT156-S2-Q21$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$A$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$B$batch07$, $batch07$ignores the fact that there are other kinds of art, such as literature and poetry, that may also occasion disagreement$batch07$, $batch07$Out of Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT156-S2-Q21$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$B$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$C$batch07$, $batch07$fails to consider whether there are valid objective standards for evaluating nonvisual art, such as music$batch07$, $batch07$Out of Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT156-S2-Q21$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$C$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$D$batch07$, $batch07$fails to consider that people who disagree about the artistic value of a given painting may be incorrectly applying the same evaluation criteria to that painting$batch07$, $batch07$Correct$batch07$, true FROM lr_questions q WHERE q.qid=$batch07$PT156-S2-Q21$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$D$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$E$batch07$, $batch07$fails to consider that the individuals judging and disagreeing about works of art may be experts in making such judgments$batch07$, $batch07$Bad Description$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT156-S2-Q21$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$E$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT156-S2-Q21$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Conclusion$batch07$, $batch07$There are no valid objective standards for judging the artistic value of a painting or sculpture.$batch07$), (1, $batch07$Evidence$batch07$, $batch07$For some art, beauty is in the eye of the beholder: a painting one person finds valuable may strike another as lacking value.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$The argument goes from "people disagree" to "there is no correct standard". That is a gap. People disagree about math problems too, and math still has right answers. One way the gap shows up: two people might share the same standard and one of them applies it badly.$batch07$), (3, $batch07$Goal$batch07$, $batch07$The argument overlooks that disagreement can come from mistakes, not from the absence of a standard.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT156-S2-Q21$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$The adage isn't the only support. The philosopher also points to actual disagreement between viewers. And the flaw isn't that the adage is unproven; even granting it, the conclusion doesn't follow.$batch07$), ($batch07$B$batch07$, $batch07$The conclusion is only about paintings and sculpture. Other art forms don't matter here.$batch07$), ($batch07$C$batch07$, $batch07$Same problem. Music is outside the conclusion, so failing to consider it is not a flaw.$batch07$), ($batch07$D$batch07$, $batch07$If both viewers use the same criteria and one applies them wrongly, there is a standard, and the disagreement is just an error. The philosopher never rules this out.$batch07$), ($batch07$E$batch07$, $batch07$If the judges were experts and still disagreed, that would, if anything, help the philosopher. It doesn't expose a gap.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT156-S2-Q21$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
